import React, { useState, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api"; // Axios instance
import { AuthContext } from "../contexts/AuthContext";

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [otp, setOtp] = useState("");
  const [otpRequired, setOtpRequired] = useState(false);
  const [tempToken, setTempToken] = useState(null);
  const [error, setError] = useState("");
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    try {
      if (!otpRequired) {
        // Step 1: submit email + password
        const res = await api.post("/auth/login", { email, password });
        const data = res.data;

        if (data.otpRequired) {
          // Student has TOTP enabled, ask for OTP
          setOtpRequired(true);
          setTempToken(data.tempToken); // store temporary token
        } else {
          // Admin/Comelec login
          login({ token: data.token, user: data.user });
          if (data.user.role === "admin") navigate("/admin-dashboard");
          else if (data.user.role === "comelec") navigate("/comelec-dashboard");
        }
      } else {
        // Step 2: submit OTP
        const res = await api.post(
          "/auth/login",
          { email, password, totp: otp },
          { headers: { Authorization: `Bearer ${tempToken}` } }
        );
        const { token, user } = res.data;
        login({ token, user });
        if (user.role === "admin") navigate("/admin-dashboard");
        else if (user.role === "comelec") navigate("/comelec-dashboard");
        else navigate("/"); // student home
      }
    } catch (err) {
      console.error(err);
      setError(err.response?.data?.error || "Login failed");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100">
      <form
        onSubmit={handleSubmit}
        className="bg-white p-8 rounded-xl shadow-md w-full max-w-md flex flex-col gap-4"
      >
        <h2 className="text-2xl font-bold text-gray-800 text-center">Login</h2>

        {error && <p className="text-red-600 text-center">{error}</p>}

        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
          className="p-2 border rounded border-gray-300 focus:outline-none focus:ring focus:ring-indigo-200"
        />
        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          className="p-2 border rounded border-gray-300 focus:outline-none focus:ring focus:ring-indigo-200"
        />

        {otpRequired && (
          <input
            type="text"
            placeholder="Enter OTP"
            value={otp}
            onChange={(e) => setOtp(e.target.value)}
            required
            className="p-2 border rounded border-gray-300 focus:outline-none focus:ring focus:ring-indigo-200"
          />
        )}

        <button
          type="submit"
          className="bg-indigo-600 text-white py-2 rounded hover:bg-indigo-700 transition"
        >
          {otpRequired ? "Verify OTP" : "Login"}
        </button>
      </form>
    </div>
  );
}
